INSERT INTO sources (source_id, source_type, title, scope) VALUES
 ('SRC_DDD_BIBLE','reference work','Dictionary of Deities and Demons in the Bible','reuse — van der Toorn, Becking & van der Horst (eds.), DDD (2nd ed., Brill 1999); already present in DB (source_id SRC_DDD_BIBLE), do not re-insert')
INSERT INTO _e VALUES
 ('ENT_LEV_BIBLICAL_DEITIES','Biblically-Attested Minor Levantine Deities','collective','collective','Canaanite/Ugaritic','pantheon/collective','B','Hub collective for the DDD set of minor Northwest-Semitic gods named (mostly polemically) in the Hebrew Bible — the foreign gods of Samaria''s resettled peoples (2 Kings 17) and Philistine/Sidonian local cults; grouping entity, not a worshipped deity.'),
 ('ENT_LEV_BAAL_ZEBUB','Baal-Zebub of Ekron','deity','deity','Canaanite/Ugaritic','healing/oracle/storm-god local cult','B','Philistine city-god of Ekron consulted as a healing oracle by King Ahaziah (2 Kings 1). Name = ''Lord of the Flies'', almost certainly a Hebrew polemical distortion of an original Baal epithet (''zbl/Zebul'' = ''Prince'', as at Ugarit). The ORIGINAL deity behind the later Christian demon Beelzebub. Homonym note: distinct from the demon Beelzebul (ENT_CHR_BEELZEBUL), which is his reception.'),
 ('ENT_LEV_ASHIMA','Ashima of Hamath','deity','deity','Canaanite/Ugaritic','city/tutelary deity','B','Deity of the people of Hamath, named among the gods made by Samaria''s resettled peoples (2 Kings 17:30). Plausibly connected to a NW-Semitic goddess Asham/Ashima attested at Elephantine (Anat-Ashima) and possibly to the Aramaean cult of Hamath; later rabbinic tradition imagined her as a goat/bald-figure idol.'),
 ('ENT_LEV_ADRAMMELECH','Adrammelech','deity','deity','Canaanite/Ugaritic','underworld/sacrificial deity','C','God of Sepharvaim to whom child sacrifice (''passing through fire'') was made (2 Kings 17:31). Name = ''Adad/Adar is king'' or ''the king is exalted''; identity debated — linked variously to Adad, a solar/Molek-type cult, or an Aramaean/Assyrian deity. Paired with Anammelech.'),
 ('ENT_LEV_ANAMMELECH','Anammelech','deity','deity','Canaanite/Ugaritic','astral/sacrificial deity','C','God of Sepharvaim receiving child sacrifice alongside Adrammelech (2 Kings 17:31). Name = ''Anu/Anath is king''; proposed links to the Mesopotamian sky-god Anu, a lunar deity, or (via ''Anath-melek'') the Canaanite goddess Anat. Identity uncertain.'),
 ('ENT_LEV_NIBHAZ','Nibhaz','deity','deity','Canaanite/Ugaritic','tutelary deity (obscure)','C','God of the Avvites, named with Tartak among Samaria''s resettled gods (2 Kings 17:31). Etymology obscure and possibly a scribal corruption; later Jewish tradition fancifully described a dog-shaped idol. No independent epigraphic attestation.'),
 ('ENT_LEV_TARTAK','Tartak','deity','deity','Canaanite/Ugaritic','tutelary deity (obscure)','C','God of the Avvites, paired with Nibhaz (2 Kings 17:31). Etymology uncertain (possibly an Elamite/Iranian theonym or scribal corruption); rabbinic tradition imagined an ass-shaped idol. No independent attestation outside the biblical notice.'),
 ('ENT_LEV_ASTRONOE','Astronoe','deity','deity','Canaanite/Ugaritic','love/healing goddess (Sidonian)','C','Sidonian goddess known from Damascius (Life of Isidore): a mountain-mother/huntress who, on the youth Eshmun''s self-mutilation, revives and deifies him. Generally read as a hellenized aspect of Astarte tied to the Eshmun healing cult at Sidon.');
